<template><el-dialog :model-value="modelValue" title="导入机器人模型" width="680" @close="$emit('update:modelValue',false)"><el-steps :active="step" finish-status="success"><el-step title="选择来源"/><el-step title="配置"/><el-step title="载入"/></el-steps><div class="wizard-body"><label>模型文件或目录<div class="path-row"><el-input v-model="path" placeholder="URDF、Xacro、MJCF 或模型目录"/><el-button @click="pick('file')">浏览文件</el-button><el-button @click="pick('directory')">目录</el-button></div></label><el-alert v-if="format==='step'" type="warning" :closable="false" title="STEP 需要交互式适配"><p>在 step2urdf 中定义 Link、Joint、质量和惯量，导出 URDF ZIP 后返回此处导入。</p><p v-if="adapter">适配器：{{adapter.available?'可启动':adapter.reason}}</p><el-button :disabled="!adapter?.available" @click="launchAdapter">启动本地 step2urdf</el-button><el-button @click="pickExport">选择导出的 ZIP</el-button></el-alert><label>入口文件（目录导入时可选）<el-input v-model="entry" placeholder="由候选分析后选择"/></label><label>Package map（可选）<el-input v-model="packageMap" placeholder="YAML 路径"/></label><label>Xacro 参数<el-input v-model="argumentsText" type="textarea" :rows="3" placeholder="name=value，每行一个"/></label><el-alert title="默认辅助模式：低置信度候选必须确认" type="info" :closable="false"/></div><template #footer><el-button @click="$emit('update:modelValue',false)">取消</el-button><el-button type="primary" :loading="store.busy" :disabled="!path||format==='step'" @click="load">导入并显示</el-button></template></el-dialog></template>
<script setup lang="ts">import {ref} from 'vue';import {ElMessage} from 'element-plus';import {analyzePath,launchStepAdapter,pickPath,type StepAdapterStatus} from '@/api/models';import {useEditorStore} from '@/stores/editor';defineProps<{modelValue:boolean}>();const emit=defineEmits(['update:modelValue']);const store=useEditorStore();const path=ref('');const entry=ref('');const packageMap=ref('');const argumentsText=ref('');const step=ref(0);const format=ref('');const adapter=ref<StepAdapterStatus|null>(null);async function inspect(){if(!path.value)return;const result=await analyzePath(path.value);format.value=result.format;adapter.value=result.stepAdapter||null;step.value=1}async function pick(kind:'file'|'directory'){path.value=(await pickPath(kind)).path;await inspect()}async function pickExport(){path.value=(await pickPath('file')).path;await inspect()}async function launchAdapter(){try{const status=await launchStepAdapter();window.open(status.url,'step2urdf');ElMessage.success('step2urdf 已启动；首次加载 OpenCascade 可能需要一些时间')}catch(error){ElMessage.error(String(error))}}async function load(){const args=Object.fromEntries(argumentsText.value.split('\n').filter(Boolean).map(x=>x.split('=',2) as [string,string]));try{await store.open({path:path.value,entry:entry.value||undefined,arguments:args,package_map_path:packageMap.value||undefined});step.value=3;emit('update:modelValue',false);ElMessage.success('模型已载入三维工作区')}catch(e){ElMessage.error(String(e))}}</script>
